  var line=raw.trim();if(!line||line.charAt(0)==='#')return;
  var i=line.indexOf('#'),endpointText=(i>=0?line.slice(0,i):line).trim(),remark=i>=0?line.slice(i+1).trim():'';
  remark=remark.replace(/\$(socks5|http|https|turn|sstp):\/\/.*$/i,'').trim();
  var item=parseEndpoint(endpointText);if(!item)return;
  var key=item.endpoint.toLowerCase();if(seen[key])return;seen[key]=true;
  out.push({host:item.host,port:item.port,endpoint:item.endpoint,remark:remark})
