function hint(){if(!state||!state.hint)return;var list=selected();if(!state.entries.length)state.hint.textContent='当前自定义优选中没有可选的域名/IP';else if(list.length>1)state.hint.textContent='已选 '+list.length+' 个；点击“添加”会按每个入口批量追加链式节点';else if(list.length===1)state.hint.textContent='已选 1 个；入口已同步到上方字段';else state.hint.textContent='可单选或按住 Command/Ctrl 多选；选择后会同步优选域名/IP'}
