 var base=String(name&&name.value||'').replace(/[\r\n]+/g,' ').trim()||(add.dataset.defaultNodeName||'链式'+String(validProtocol).toUpperCase()+'代理');
 var lines=list.map(function(option,index){var endpoint=option.value;if(!option.dataset.port){var shared=String((el('chainProxyPort')||{}).value||'').trim();if(shared)endpoint=option.dataset.host+':'+shared}return endpoint+'#'+base+' ['+(index+1)+'/'+list.length+']$'+validProtocol+'://'+validAddress});
